const allTxs = $input.all().map(item => item.json);

if (allTxs.length === 0) {
  return { json: { response: "No transactions found to analyze." } };
}

let categoryTotals = {};
let vendorTotals = {};
let totalSpent = 0;

// Analyze the last 100 transactions for relevance
const recentTxs = allTxs.slice(-100);

recentTxs.forEach(tx => {
  const amt = parseFloat(tx.amount);
  if (!isNaN(amt) && (!tx.type || tx.type.toLowerCase() !== 'income')) {
    totalSpent += amt;

    const cat = tx.category || 'Uncategorized';
    categoryTotals[cat] = (categoryTotals[cat] || 0) + amt;

    const vendor = tx.vendor || 'Unknown';
    vendorTotals[vendor] = (vendorTotals[vendor] || 0) + amt;
  }
});

// Sort to find top spending
const topCategories = Object.entries(categoryTotals).sort((a, b) => b[1] - a[1]).slice(0, 5);
const topVendors = Object.entries(vendorTotals).sort((a, b) => b[1] - a[1]).slice(0, 5);

let report = `EXPENSE ANALYSIS (Last 100 Txs)\nTotal Spent: ₹${totalSpent}\n\nTop Categories:\n`;
topCategories.forEach(c => report += `- ${c[0]}: ₹${c[1]}\n`);

report += `\nTop Vendors:\n`;
topVendors.forEach(v => report += `- ${v[0]}: ₹${v[1]}\n`);

return { json: { response: report } };
